SELECT
TOTLE_TRADE_ID
FROM
TRD_FIN_PRODUCT_DEAL_TOTAL

    TRADE_STATUS = #{TRADE_STATUS_01}
    AND (IS_CANCEL IS NULL OR IS_CANCEL = 'N')

        AND TRADE_DATE = #{dealDate,jdbcType=DATE}


        AND BUSI_TYPE = #{busiType,jdbcType=DATE}



            #{ps,jdbcType=VARCHAR}




            #{portfolioId,jdbcType=VARCHAR}

SELECT


DISTINCT NVL(C.P_TOTLE_TRADE_ID, A.TOTLE_TRADE_ID)

FROM
TRD_PRODUCT_DEAL A
LEFT JOIN SETTLE_TRANS_TG_MAPPING B
ON A.TOTLE_TRADE_ID = B.TRADE_ID_TG
INNER JOIN TRD_FIN_PRODUCT_DEAL_TOTAL C
ON A.TOTLE_TRADE_ID = C.TOTLE_TRADE_ID
left join SETTLE_TRANS_TG_MAPPING B2
on C.P_TOTLE_TRADE_ID = B2.TRADE_ID_TG
LEFT JOIN SETTLE_TRANS_DATA_STATUS D
ON D.TRADE_ID = nvl(B.TRADE_ID, B2.TRADE_ID)

    A.TRADE_STATUS = #{TRADE_STATUS_01}
    AND (A.IS_CANCEL IS NULL OR A.IS_CANCEL = 'N')
    AND (D.CHECK_RESULT is null or D.CHECK_RESULT = '0')

        AND TO_CHAR(nvl(B.DEAL_DATE, B2.DEAL_DATE), 'yyyy-MM-dd') = #{dealDateStr,jdbcType=VARCHAR}


        AND C.BUSI_TYPE = #{busiType,jdbcType=VARCHAR}



            #{busiTypeItem,jdbcType=VARCHAR}




            #{ps,jdbcType=VARCHAR}




            #{portfolioId,jdbcType=VARCHAR}




            #{ps,jdbcType=VARCHAR}




            #{tgBusiType,jdbcType=VARCHAR}



UNION
SELECT
DISTINCT A.TOTLE_TRADE_ID
FROM
TRD_PRODUCT_DEAL A
LEFT JOIN SETTLE_TRANS_TG_MAPPING B
ON A.TOTLE_TRADE_ID = B.TRADE_ID_TG
INNER JOIN TRD_FIN_PRODUCT_DEAL_TOTAL C
ON A.TOTLE_TRADE_ID = C.TOTLE_TRADE_ID
left join SETTLE_TRANS_TG_MAPPING B2
on C.P_TOTLE_TRADE_ID = B2.TRADE_ID_TG
LEFT JOIN TRD_PRODUCT_DEAL_ADD D
ON A.TRADE_ID = D.TRADE_ID

    A.TRADE_STATUS = #{TRADE_STATUS_01}
    AND (A.IS_CANCEL IS NULL OR A.IS_CANCEL = 'N')
    AND B.TRADE_ID is null
    AND B2.TRADE_ID is null

        AND TO_CHAR(A.TRADE_DATE, 'yyyy-MM-dd') = #{dealDateStr,jdbcType=VARCHAR}


        AND C.BUSI_TYPE = #{busiType,jdbcType=VARCHAR}



            #{busiTypeItem,jdbcType=VARCHAR}






                    #{ps,jdbcType=VARCHAR}

                OR (A.PS = #{PS_01} AND A.TRADE_MARKET_MODE != #{SHARES_TRADE_MARKET_01})

                    #{ps,jdbcType=VARCHAR}

                AND D.PURCH_MODLE != #{PURCH_MODLE_02}))





                    #{ps,jdbcType=VARCHAR}






            #{tgBusiType,jdbcType=VARCHAR}




            #{tradeMarket,jdbcType=VARCHAR}




            #{ps,jdbcType=VARCHAR}




            #{tgBusiType,jdbcType=VARCHAR}

